import sys
from collections import deque

def main():
    board = []
    for _ in range(3):
        row = list(map(int, sys.stdin.readline().split()))
        board.append(row)
    print(bfs(board))

def bfs(board):
    start = tuple(tuple(row) for row in board)
    goal = ((1, 2, 3), (4, 5, 6), (7, 8, 0))
    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        cur, dist = queue.popleft()
        if cur == goal:
            return dist
        for neighbor in neighbors(cur):
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append((neighbor, dist + 1))

def neighbors(state):
    yx = find_zero(state)
    y, x = yx
    nbs = []
    for dy, dx in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
        ny, nx = y + dy, x + dx
        if 0 <= ny < 3 and 0 <= nx < 3:
            new = list(list(row) for row in state)
            new[y][x], new[ny][nx] = new[ny][nx], new[y][x]
            nbs.append(tuple(tuple(row) for row in new))
    return nbs

def find_zero(state):
    for y in range(3):
        for x in range(3):
            if state[y][x] == 0:
                return (y, x)
    return None  # should never happen

