def is_valid_sudoku(grid):
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]

    for r in range(9):
        for c in range(9):
            num = grid[r][c]
            if num == 0:
                continue
            if num in rows[r]:
                return False
            if num in cols[c]:
                return False
            box_index = (r // 3) * 3 + (c // 3)
            if num in boxes[box_index]:
                return False
            rows[r].add(num)
            cols[c].add(num)
            boxes[box_index].add(num)

    return True

import json
import sys

def main():
    input_line = sys.stdin.readline()
    try:
        data = json.loads(input_line)
    except json.JSONDecodeError:
        print('<table></table>')
        return
    if not data:
        print('<table></table>')
        return

    all_keys = set()
    for entry in data:
        all_keys.update(entry.keys())
    headers = sorted(all_keys)

    print('<table border=\'1\'>')
    print('<tr>' + ''.join(f'<th>{k}</th>' for k in headers) + '</tr>')
    for entry in data:
        row = []
        for k in headers:
            val = entry.get(k, None)
            if val is None:
                row.append('N/A')
            else:
                row.append(val)
        print('<tr>' + ''.join(f'<td>{cell}</td>' for cell in row) + '</tr>')
    print('</table>')

